class Solution {
public:
    string findLongestWord(string s, vector<string>& dictionary) {
        auto isSubseq = [&](const string& w) {
            int i = 0;
            for (char ch : s) {
                if (i < (int)w.size() && w[i] == ch) i++;
            }
            return i == (int)w.size();
        };
        string best = "";
        for (const string& w : dictionary) {
            if (isSubseq(w)) {
                if (w.size() > best.size() || (w.size() == best.size() && w < best)) {
                    best = w;
                }
            }
        }
        return best;
    }
};

class Solution {
    public String findLongestWord(String s, List<String> dictionary) {
        String best = "";
        for (String w : dictionary) {
            if (isSubseq(w, s)) {
                if (w.length() > best.length() || (w.length() == best.length() && w.compareTo(best) < 0)) {
                    best = w;
                }
            }
        }
        return best;
    }

    private boolean isSubseq(String w, String s) {
        int i = 0;
        for (int j = 0; j < s.length() && i < w.length(); j++) {
            if (w.charAt(i) == s.charAt(j)) i++;
        }
        return i == w.length();
    }
}

var findLongestWord = function(s, dictionary) {
    const isSubseq = (w) => {
        let i = 0;
        for (let j = 0; j < s.length && i < w.length; j++) {
            if (w[i] === s[j]) i++;
        }
        return i === w.length;
    };
    let best = "";
    for (const w of dictionary) {
        if (isSubseq(w)) {
            if (w.length > best.length || (w.length === best.length && w < best)) {
                best = w;
            }
        }
    }
    return best;
};
